SourceCode.Declaration:
/// <summary>
/// Take place with 'search again' in GUPParameters is set to true.
/// That is, all priorities set in Trade Agreement price component are disabled, 
/// and [Valid] Trade Agreement with overall lowest price is returned.
/// </summary>
internal class GUPComparatorTradeAgreementLineAggregationPriceOnly implements GUPIComparator
{
}

Method.Source:
public int compare(anytype o1, anytype o2)
{
    GUPPriceEngineTradeAgreementLineAggregation obj1 = o1;
    GUPPriceEngineTradeAgreementLineAggregation obj2 = o2;

    // Sort by price in ascending order.
    if (obj1.parmLowestPrice() > obj2.parmLowestPrice())
    {
        return 1;
    }
    else if (obj1.parmLowestPrice() < obj2.parmLowestPrice())
    {
        return -1;
    }
    return 0;
}
